from datetime import datetime

class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time")

        # Calculate duration in hours
        duration = exit - entry
        total_seconds = duration.total_seconds()
        hours = total_seconds / 3600.0

        # Check for stays longer than 24 hours
        if hours > 24.0:
            return round(200.00, 2)

        # Check for stays of at most 15 minutes (0.25 hours)
        if hours <= 0.25:
            return 0.00

        # Calculate fee for stays longer than 15 minutes
        # Charge for the whole duration (including first 15 minutes)
        fee_amount = hours * self.hourly_rate
        return round(fee_amount, 2)
